SELECT json_build_object('principals', (SELECT coalesce(json_agg(json_build_array(l.principal, l.tier, l.board, l.paired, l.pending, l.code_expires_at, l.created_at, l.paired_at, l.revoked_at, l.now, l.last_seen_at, l.stored, l.owned) ORDER BY l.principal), '[]'::json) FROM (SELECT p.principal, p.tier, p.board, p.token_hash IS NOT NULL AS paired, p.code_hash IS NOT NULL AS pending, p.code_expires_at, p.created_at, p.paired_at, p.revoked_at, EXTRACT(EPOCH FROM clock_timestamp())::double precision AS now, a.last_seen_at, TRUE AS stored, COALESCE((to_jsonb(p) ->> 'owned')::boolean, TRUE) AS owned FROM public.principals p LEFT JOIN public.principal_activity a ON a.principal = p.principal UNION ALL SELECT a.principal, NULL, NULL, FALSE, FALSE, NULL, NULL, NULL, NULL, EXTRACT(EPOCH FROM clock_timestamp())::double precision, a.last_seen_at, FALSE, NULL FROM public.principal_activity a WHERE NOT EXISTS (SELECT 1 FROM public.principals p WHERE p.principal = a.principal)) l), 'rejected', (SELECT coalesce(json_agg(json_build_array(hash_prefix, rejections, first_seen_at, last_seen_at) ORDER BY last_seen_at DESC, hash_prefix), '[]'::json) FROM public.rejected_bearers));